def prod_signs(arr):
    if not arr:
        return None

    product_sign = 1
    absolute_sum = 0

    for num in arr:
        if num < 0:
            product_sign *= -1
        elif num > 0:
            product_sign *= 1
        else:
            product_sign *= 0
        absolute_sum += abs(num)

    return absolute_sum * product_sign

